import "aos/dist/aos.css";
import {
    FaCertificate,
    FaCheckCircle,
    FaClipboardCheck,
    FaIndustry,
    FaComments,
    FaWhatsapp,
} from "react-icons/fa";
import { Certifications1, Certifications2, Certifications3, Client1, Client2, Client3, Client4 } from "../../asset/image";

function Certifications() {
    //-----------------------STATE VIEWS-----------------------//
    const certificationServices = [
        {
            title: "ISO Certification",
            description:
                "Pendampingan sertifikasi ISO untuk meningkatkan sistem manajemen, kualitas operasional, dan kepercayaan mitra bisnis.",
            icon: FaCertificate,
        },
        {
            title: "Halal Certification",
            description:
                "Layanan pendampingan sertifikasi halal sesuai regulasi yang berlaku untuk menjamin kehalalan produk dan proses.",
            icon: FaCheckCircle,
        },
        {
            title: "Business & Compliance Certification",
            description:
                "Sertifikasi dan pendampingan kepatuhan usaha terhadap standar hukum, industri, dan regulasi terkait.",
            icon: FaClipboardCheck,
        },
        {
            title: "Product & Quality Certification",
            description:
                "Pendampingan sertifikasi mutu dan kualitas produk untuk meningkatkan daya saing di pasar nasional maupun internasional.",
            icon: FaIndustry,
        },
        {
            title: "Certification Consultation",
            description:
                "Konsultasi menyeluruh terkait kebutuhan sertifikasi yang disesuaikan dengan jenis usaha dan sektor industri.",
            icon: FaComments,
        },
    ];
    const certificationShowcases = [
        {
            title: "Sertifikasi JPT ( Jasa Pengurusan Transportasi )",
            description:
                "Kolaborasi Regarde Certification & Aston Patent untuk penguatan kepatuhan regulasi dan branding perusahaan PT Nippon Express Indonesia",
            image: Certifications1,
            tag: "Sertifikasi Standar",
        },
        {
            title: "Sertifikasi ISO 9001:2015",
            description:
                "Regarde Certifitacion menyerahkan Sertifikat ISO 9001:2015 kepada PT Nippon Express Indonesia atas penerapan Sistem Manajemen Mutu untuk memastikan layanan memenuhi standar pelanggan dan peraturan secara konsisten serta meningkatkan kepuasan pelanggan",
            image: Certifications2,
            tag: "Sertifikasi ISO",
        },
        {
            title: "Sertifikasi BPOM",
            description:
                "Regarde Certifitacion menyerahkan Sertifikat Izin Edar BPOM (Badan Pengawas Obat dan Makanan) untuk produk Tepung Bumbu Deris Jempol di Indonesia",
            image: Certifications3,
            tag: "Sertifikasi BPOM",
        },
    ];
    const clients = [
        { name: "Client 1", logo: Client1 },
        { name: "Client 2", logo: Client2 },
        { name: "Client 3", logo: Client3 },
        { name: "Client 4", logo: Client4 },
    ];
    const WA_NUMBER = "6281213094426";
    //-----------------------STATE VIEWS-----------------------//

    //------------------------FUNCTIONS------------------------//
    const getWaLink = (serviceName: string) => {
        const message = `Halo Regarde,%0ASaya ingin berkonsultasi terkait layanan Certifications – ${serviceName}.%0AMohon informasinya. Terima kasih.`;
        return `https://wa.me/${WA_NUMBER}?text=${message}`;
    };
    //------------------------FUNCTIONS------------------------//

    return (
        <div className="pt-24">
            {/* CERTIFICATIONS DETAIL */}
            <section className="pb-24 bg-white" data-aos="zoom-out">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">

                    {/* ICON */}
                    <div className="flex justify-center mb-6">
                        <div className="w-20 h-20 rounded-full bg-sky-100 flex items-center justify-center">
                            <FaCertificate className="text-sky-700 text-4xl" />
                        </div>
                    </div>

                    {/* TITLE */}
                    <h2 className="text-4xl font-black text-sky-900 mb-4">
                        Certifications
                    </h2>

                    {/* DESCRIPTION */}
                    <p className="text-gray-600 max-w-2xl mx-auto mb-14">
                        Layanan pendampingan sertifikasi untuk membantu perusahaan
                        memenuhi standar, meningkatkan kredibilitas, dan memperluas peluang bisnis.
                    </p>

                    {/* SUB SERVICES */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 text-left">
                        {certificationServices.map((service, i) => {
                            const Icon = service.icon;
                            return (
                                <div
                                    key={i}
                                    data-aos="fade-up"
                                    data-aos-delay={i * 100}
                                    className="bg-white rounded-xl border border-gray-200 p-6 hover:shadow-md transition flex flex-col"
                                >
                                    {/* CONTENT */}
                                    <div className="flex items-start gap-4">
                                        <div className="text-sky-600 text-2xl mt-1">
                                            <Icon />
                                        </div>
                                        <div>
                                            <h3 className="font-semibold text-sky-900">
                                                {service.title}
                                            </h3>
                                            <p className="text-sm text-gray-600 mt-1">
                                                {service.description}
                                            </p>
                                        </div>
                                    </div>

                                    {/* WA BUTTON */}
                                    <a
                                        href={getWaLink(service.title)}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="mt-auto self-end w-10 h-10 rounded-full bg-green-600 text-white flex items-center justify-center hover:bg-green-700 transition"
                                        aria-label="Chat via WhatsApp"
                                    >
                                        <FaWhatsapp className="text-lg" />
                                    </a>
                                </div>
                            );
                        })}
                    </div>

                </div>
            </section>

            {/* CERTIFICATION SHOWCASE */}
            <section className="py-10 ">
                <div className="w-11/12 md:w-9/12 mx-auto">
                    <div className="flex flex-wrap justify-center gap-8">
                        {certificationShowcases.map((item, i) => (
                            <div key={i} data-aos="fade-up" data-aos-delay={i * 100}
                                className=" bg-white rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition flex flex-col overflow-hidden w-full sm:w-[45%] lg:w-[48%] "
                            >
                                <div className="h-96 w-full overflow-hidden">
                                    <img src={item.image} alt={item.title} className="w-full h-full object-cover hover:scale-105 transition duration-500"
                                    />
                                </div>
                                <div className="p-5 flex flex-col flex-grow">
                                    <div className="flex items-center gap-2 mb-3">
                                        <FaCertificate className="text-sky-700 text-sm" />
                                        <span className="text-xs font-semibold text-sky-700">
                                            {item.tag}
                                        </span>
                                    </div>
                                    <h4 className="text-lg font-semibold text-sky-900 mb-2">
                                        {item.title}
                                    </h4>
                                    <p className="text-sm text-gray-600 leading-relaxed">
                                        {item.description}
                                    </p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* OUR CLIENTS */}
            <section className="py-10">
                <div className="w-11/12 md:w-9/12 mx-auto text-center">
                    <h2
                        data-aos="zoom-in"
                        className="text-4xl font-black text-sky-900 mb-12">
                        Our Clients
                    </h2>
                    <div className="flex flex-wrap justify-center gap-8">
                        {clients.map((client, i) => (
                            <div key={i}
                                data-aos="fade-up"
                                data-aos-delay={i * 40}
                                className="flex items-center justify-center">
                                <img
                                    src={client.logo}
                                    alt={client.name}
                                    className="h-10 md:h-12 object-contain opacity-90 hover:opacity-100 transition"
                                />
                            </div>
                        ))}
                    </div>
                </div>
            </section>
        </div>
    );
}

export default Certifications;
